'use strict';
// Minimal offline OOXML reader: values only; formulas, macros and external links are not executed.
const CaseWorkbook=(()=>{
 async function unzip(buffer){const b=new Uint8Array(buffer),d=new DataView(buffer);let end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(d.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('不是可读取的xlsx工作簿');const out={};let pos=d.getUint32(end+16,true),total=0;for(let k=0;k<d.getUint16(end+10,true);k++){if(d.getUint32(pos,true)!==0x02014b50)throw Error('工作簿目录损坏');const method=d.getUint16(pos+10,true),size=d.getUint32(pos+20,true),full=d.getUint32(pos+24,true),nl=d.getUint16(pos+28,true),xl=d.getUint16(pos+30,true),cl=d.getUint16(pos+32,true),off=d.getUint32(pos+42,true),name=new TextDecoder().decode(b.slice(pos+46,pos+46+nl));pos+=46+nl+xl+cl;total+=full;if(total>30*1024*1024)throw Error('解压内容超过30MB，请缩小导入工作表');if(!name.endsWith('.xml')&&!name.endsWith('.rels'))continue;const begin=off+30+d.getUint16(off+26,true)+d.getUint16(off+28,true),compressed=b.slice(begin,begin+size);let raw;if(method===0)raw=compressed;else if(method===8){if(typeof DecompressionStream==='undefined')throw Error('浏览器不支持xlsx解压，请复制表格内容或导出CSV');raw=new Uint8Array(await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());}else throw Error('工作簿压缩方式不支持');out[name]=new TextDecoder().decode(raw);}return out;}
 const xml=s=>{const d=new DOMParser().parseFromString(s||'', 'application/xml');if(d.querySelector('parsererror'))throw Error('工作簿XML无法解析');return d;};
 async function read(buffer){if(buffer.byteLength>10*1024*1024)throw Error('本地原型支持10MB以内xlsx；可选择较小范围导出');const files=await unzip(buffer),workbook=xml(files['xl/workbook.xml']),rels=xml(files['xl/_rels/workbook.xml.rels']),shared=files['xl/sharedStrings.xml']?[...xml(files['xl/sharedStrings.xml']).getElementsByTagName('si')].map(x=>[...x.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];return [...workbook.getElementsByTagName('sheet')].map(sh=>{const id=sh.getAttribute('r:id'),rel=[...rels.getElementsByTagName('Relationship')].find(x=>x.getAttribute('Id')===id);let target=rel?.getAttribute('Target')||'';if(target.startsWith('/'))target=target.slice(1);else target='xl/'+target.replace(/^\.\//,'');if(!files[target])throw Error('找不到工作表：'+sh.getAttribute('name'));const sheet=xml(files[target]),rows=[];for(const row of sheet.getElementsByTagName('row')){const n=Number(row.getAttribute('r'))||rows.length+1,vals=[];for(const c of row.getElementsByTagName('c')){const letters=(c.getAttribute('r')||'A').match(/^[A-Z]+/)[0];let col=0;for(const a of letters)col=col*26+a.charCodeAt(0)-64;const v=c.getElementsByTagName('v')[0]?.textContent;let value=c.getAttribute('t')==='s'?shared[Number(v)]:c.getAttribute('t')==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):v||'';if(c.getElementsByTagName('f').length&&v===undefined)value='[公式无缓存值，请先在表格中计算并保存]';vals[col-1]=value;}rows[n-1]=vals;}return {name:sh.getAttribute('name'),rows:Array.from({length:rows.length},(_,i)=>rows[i]||[]),merges:[...sheet.getElementsByTagName('mergeCell')].map(x=>x.getAttribute('ref'))};});}
 return {read,unzip};
})();
if(typeof module!=='undefined')module.exports=CaseWorkbook;
